create table if not exists public.timeline_daw_private_review_threads(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,target_kind text not null check(target_kind in('lane','bus','master')),target_id text,start_sample bigint not null check(start_sample>=0),end_sample bigint,source_frame bigint,tempo_tick bigint,priority text not null default 'normal' check(priority in('low','normal','high','urgent')),assignee_id uuid,resolved boolean not null default false,created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_sample is null or end_sample>start_sample));
create table if not exists public.timeline_daw_private_review_messages(id text primary key,thread_id text not null references public.timeline_daw_private_review_threads(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,author_id uuid not null,body text not null check(char_length(body) between 1 and 4000),mentions jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.timeline_daw_private_review_audit(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,thread_id text not null,actor_id uuid not null,action text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.timeline_daw_private_review_threads enable row level security;alter table public.timeline_daw_private_review_messages enable row level security;alter table public.timeline_daw_private_review_audit enable row level security;
drop policy if exists timeline_daw_private_review_threads_owner on public.timeline_daw_private_review_threads;create policy timeline_daw_private_review_threads_owner on public.timeline_daw_private_review_threads using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists timeline_daw_private_review_messages_owner on public.timeline_daw_private_review_messages;create policy timeline_daw_private_review_messages_owner on public.timeline_daw_private_review_messages using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists timeline_daw_private_review_audit_owner on public.timeline_daw_private_review_audit;create policy timeline_daw_private_review_audit_owner on public.timeline_daw_private_review_audit using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
